# Equation for a=4: 16(b^3 + c^3) = 2012bc + 1006
# Constraint: b + c = 503k. We test k=1, so b + c = 503.
# c = 503 - b
# Substitute c: 16(b^3 + (503-b)^3) = 2012*b*(503-b) + 1006

def check_a4(b):
    c = 503 - b
    if b <= 0 or c <= 0 or b > c:
        return None

    lhs = 16 * (b**3 + c**3)
    rhs = 2012 * b * c + 1006

    # Check if the equation holds exactly
    return (lhs == rhs)

# We only need to check for positive integer solutions where b <= 251 (since b <= c)
# Due to the large coefficients, if b is small, LHS >> RHS.
# We check a few points to confirm the massive imbalance.
test_points = [1, 10, 100, 251]

results = {}
for b in test_points:
    result = check_a4(b)
    results[b] = result

print("Test results for a=4 with b+c=503:")
for b, result in results.items():
    if result is None:
        print(f"b={b}: Invalid point (b > c or b, c non-positive).")
    else:
        print(f"b={b}, c={503-b}: Solution found? {result}")
